tool_input.command:
# Try openviking HTTP reindex/cleanup endpoints
$base="http://127.0.0.1:1933"
foreach($ep in @('/health','/api/v1/reindex','/reindex','/api/reindex')){
  try{ $r=Invoke-WebRequest "$base$ep" -TimeoutSec 5 -UseBasicParsing; "$ep => $($r.StatusCode) $($r.Content.Substring(0,[Math]::Min(100,$r.Content.Length)))" }catch{ "$ep => $($_.Exception.Message.Split([char]10)[0])" }
}
